from itertools import combinations
from typing import NamedTuple
class P(NamedTuple): kind: str; a: int=0; b: int=0
class L(NamedTuple): kind: str; a: int=0; b: int=0
def points(q: int) -> list[P]:
    return [P("A",x,y) for x in range(q) for y in range(q)]+[P("I",m) for m in range(q)]+[P("IV")]
def lines(q: int) -> list[L]:
    return [L("O",m,b) for m in range(q) for b in range(q)]+[L("V",a) for a in range(q)]+[L("INF")]
def inc(p: P, l: L, q: int) -> bool:
    if p.kind=="A": return (l.kind=="O" and p.b==(p.a*l.a+l.b)%q) or (l.kind=="V" and p.a==l.a)
    if p.kind=="I": return (l.kind=="O" and p.a==l.a) or l.kind=="INF"
    return l.kind in {"V","INF"}
def audit(q: int) -> tuple[int,int]:
    ps,ls=points(q),lines(q)
    bp=sum(sum(inc(p,l,q) and inc(r,l,q) for l in ls)!=1 for p,r in combinations(ps,2))
    bl=sum(sum(inc(p,l,q) and inc(p,k,q) for p in ps)!=1 for l,k in combinations(ls,2))
    return bp,bl
for q in (2,3,5,7): print(q, q*q+q+1, audit(q))

