    if p.kind=="I": return (l.kind=="O" and p.a==l.a) or l.kind=="INF"
    return l.kind in {"V","INF"}
def audit(q: int) -> tuple[int,int]:
    ps,ls=points(q),lines(q)
    bp=sum(sum(inc(p,l,q) and inc(r,l,q) for l in ls)!=1 for p,r in combinations(ps,2))
    bl=sum(sum(inc(p,l,q) and inc(p,k,q) for p in ps)!=1 for l,k in combinations(ls,2))
    return bp,bl
for q in (2,3,5,7): print(q, q*q+q+1, audit(q))

